INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c1c2c3d4-3301-4000-8000-000000000001', 'b1b2c3d4-3333-4000-8000-000000000003', 1, 'O que é Vocação?', 'Fundamentos do chamado divino', '{"text": "A voca\u00e7\u00e3o n\u00e3o \u00e9 apenas uma profiss\u00e3o ou estado de vida \u2014 \u00e9 o chamado \u00fanico e irrepet\u00edvel que Deus faz a cada pessoa. Santo Tom\u00e1s de Aquino ensina que Deus nos criou com um prop\u00f3sito espec\u00edfico, inscrito em nossa pr\u00f3pria natureza.\n\n\"Deus n\u00e3o nos chama porque somos bons; Ele nos torna bons porque nos chama.\" \u2014 S\u00e3o Jo\u00e3o Cris\u00f3stomo\n\nExistem quatro voca\u00e7\u00f5es fundamentais na Igreja:\n1. **Matrim\u00f4nio** \u2014 chamado \u00e0 santidade conjugal e familiar\n2. **Sacerd\u00f3cio** \u2014 chamado a servir como alter Christus\n3. **Vida Consagrada** \u2014 chamado \u00e0 radicalidade evang\u00e9lica\n4. **Vida Leiga** \u2014 chamado \u00e0 santifica\u00e7\u00e3o no mundo\n\nO discernimento come\u00e7a com a disposi\u00e7\u00e3o de dizer: \"Senhor, o que queres que eu fa\u00e7a?\" (At 9,6)", "scripture": "Jr 1,5 \u2014 Antes de te formar no ventre materno, eu te conheci; antes de sa\u00edres do seio, eu te consagrei."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;